vector[n_obs] X2;
vector[n_obs] Z;
int<lower=0, upper=1> y[n_obs];
}

parameters {
real<lower=0> ho; // Z independent hazard
real<lower=0> a0[n_grp]; // grp random effect on alpha
real<lower=0> a_GM_grp; //  grp mean effect on baseline
real<lower=0> a_sd_grp; // grp sd effect on alpha
real a1; // effect of X1 on alpha
real a2; // effect of X2 on alpha
real<upper=0> b0[n_grp]; // grp random effect on beta
real<upper=0> b_GM_grp; // grp mean effect on beta
real<lower=0> b_sd_grp; // grp sd effect on beta
real b1; // X1 effect on beta
real b2; // X2 effect on beta
}

transformed parameters {
real<lower=0, upper=1> p[n_obs];
real<lower=0> alpha[n_obs];
vector[n_obs] beta;

for(i in 1:n_obs){
alpha[i] <- a0[grp[i]] * (X1[grp[i]]^a1) * (X2[i]^a2);
