}
}

model {
for (s in 1:n_grp) {
a0[s] ~ normal(a_GM_grp, a_sd_grp) T[0.0,]; //must be positive
b0[s] ~ normal(b_GM_grp, b_sd_grp) T[,0.0]; //must be negative
}
y ~ bernoulli(p);
}

