real<lower=0>          obs_p[n_clients, max_transactions]; /* p_ij */
real                   obs_z[n_clients, max_transactions]; /* z_ij */
vector[n_categories]   x_c[n_clients, max_transactions];
/* ^^ This must be in 1-of-k indicator vector. */

}

parameters {
/* Random effects priors */
vector[dim_t]          mu_t;
vector[dim_q]          mu_q;
vector[dim_w]          mu_w;
real                   mu_lambda;

cov_matrix[dim_t]      inv_Sigma_t;
cov_matrix[dim_q]      inv_Sigma_q;
cov_matrix[dim_w]      inv_Sigma_w;
real<lower=0>          sig_lambda;

/* Random effects */
vector[dim_t]          beta_t[n_clients];
vector[dim_q]          beta_q[n_clients];
vector[dim_w]          beta_w[n_clients];
real                   lambda1[n_clients]; /* intercept for control function */

/* Fixed effects */
real<lower=0> sigma; /* for q */
real<lower=0> alpha; /* for t */

/* Control function */
real sigma_xi;
real sigma_p;
real gamma;
real lambda2;

vector[n_categories] lambda_categories;

/* N(0,1) draw for each iteration */
matrix[n_clients, max_transactions] b;

}

model {

/* Fixed effect priors */
sigma ~ normal(sigma_mean, sigma_sd); // scale parameter for log normal
alpha ~ normal(alpha_mean, alpha_sd); // scale parameter for log logistic (will be transformed in function)

/* Priors for random effects */
mu_t  ~ multi_normal_prec(mu_t0, inv_V_t0);
mu_q  ~ multi_normal_prec(mu_q0, inv_V_q0);
mu_w  ~ multi_normal_prec(mu_w0, inv_V_w0);
mu_lambda ~ normal(mu_lambda_mean,mu_lambda_sd);

inv_Sigma_t ~ wishart(df_t0, S_t0);
inv_Sigma_q ~ wishart(df_q0, S_q0);
inv_Sigma_w ~ wishart(df_w0, S_w0);
sig_lambda  ~ cauchy(sig_lambda_mean,sig_lambda_sd);

/* Priors for control function */
sigma_xi      ~ normal(sigma_xi_mean,sigma_xi_sd);
sigma_p       ~ normal(sigma_p_mean,sigma_p_sd);
gamma         ~ normal(gamma_mean,gamma_sd);
lambda2       ~ normal(lambda2_mean,lambda2_sd); // cost

lambda_categories ~ normal(mu_lambda_cat, sigma_lambda_cat);

/* Hierarchical variables */
for (i in 1:n_clients) {

  /* Random effects */
  beta_t[i]  ~ multi_normal_prec(mu_t, inv_Sigma_t);
  beta_q[i]  ~ multi_normal_prec(mu_q, inv_Sigma_q);
  beta_w[i]  ~ multi_normal_prec(mu_w, inv_Sigma_w);

  /* control function intercept */
  lambda1[i] ~ normal(mu_lambda,sig_lambda);

  /* Likelihood */
  for (j in 1:n_transactions[i]) {

    if(j < n_transactions[i]){
      // Add the likelihood term for every observation but the last one

      increment_log_prob(log_two_logistic_logpdf(obs_t[i,j], dot_product(x_t[i,j], beta_t[i]), exp(alpha)));

      obs_q[i,j] ~ lognormal(dot_product(x_q[i,j], beta_q[i]), exp(sigma));

      // Control function
      // Step 1 - price equation
      obs_p[i,j] ~ lognormal(lambda1[i] + lambda2*obs_z[i,j] + dot_product(x_c[i,j],lambda_categories), sigma_p^2);

      // Step 2 - add correlation terms into the logit utility
      b[i,j] ~ normal(0,1);
      obs_w[i,j] ~ bernoulli_logit(dot_product(x_w[i,j], beta_w[i]) +
                gamma*(obs_p[i,j] - lambda1[i] - lambda2*obs_z[i,j] - dot_product(x_c[i,j],lambda_categories)) + sigma_xi*b[i,j]);

    } else {
      // The last observation of each client is truncated - add the survival term
      increment_log_prob(log_two_logistic_survival(obs_t[i,n_transactions[i]],dot_product(x_t[i,j], beta_t[i]),exp(alpha)));
    }
  }

}

