               sigma_p_mean  = 0.5, sigma_p_sd  = sqrt(2), # scale parameter

               mu_lambda_mean = 0, mu_lambda_sd = 10, # this is the only RE in the control function
               sig_lambda_mean = 0, sig_lambda_sd = 2.5,

